def max_at_most_3_bad_days(sales):
  l, r = 0, 0
  window_bad_days = 0
  cur_max = 0
  while r < len(sales):
    can_grow = sales[r] >= 10 or window_bad_days < 3
    if can_grow:
      if sales[r] < 10:
        window_bad_days += 1
      r += 1
      cur_max = max(cur_max, r - l)
    else:
      if sales[l] < 10:
        window_bad_days -= 1
      l += 1
  return cur_max

