function maxAtMost3BadDays(sales) {
  let l = 0,
    r = 0;
  let windowBadDays = 0;
  let curMax = 0;
  while (r < sales.length) {
    const canGrow = sales[r] >= 10 || windowBadDays < 3;
    if (canGrow) {
      if (sales[r] < 10) {
        windowBadDays++;
      }
      r++;
      curMax = Math.max(curMax, r - l);
    } else {
      if (sales[l] < 10) {
        windowBadDays--;
      }
      l++;
    }
  }
  return curMax;
}

