class MaxAtMost3BadDays {
  public int solve(int[] sales) {
    int l = 0, r = 0;
    int windowBadDays = 0;
    int curMax = 0;
    while (r < sales.length) {
      boolean canGrow = sales[r] >= 10 || windowBadDays < 3;
      if (canGrow) {
        if (sales[r] < 10) {
          windowBadDays++;
        }
        r++;
        curMax = Math.max(curMax, r - l);
      } else {
        if (sales[l] < 10) {
          windowBadDays--;
        }
        l++;
      }
    }
    return curMax;
  }
}

